import{_ as e}from"./chunks/interactive-mode.GWxR--kb.js";import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.LX5S0jbT.js";const g=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md"}'),o={name:"quickstart.md"};function l(r,s,h,p,d,c){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>Pi runs in your terminal and works with files on your machine. To use it, you need access to a model through a supported provider. This can be a subscription, an API key, or a local model.</p><p>For native Windows setup, read <a href="./windows.html">Windows Setup</a>. For Android, read <a href="./termux.html">Termux Setup</a>.</p><h2 id="_1-install-pi" tabindex="-1">1. Install Pi <a class="header-anchor" href="#_1-install-pi" aria-label="Permalink to &quot;1. Install Pi&quot;">​</a></h2><p>On macOS or Linux, you can use the installer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pi.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>The installer pins all dependencies and updates Pi with <code>pi update</code>. Alternatively, install Pi from npm, which does not pin transitive dependencies. This requires Node.js 22.19 or newer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @earendil-works/pi-coding-agent</span></span></code></pre></div><p>Pi does not require dependency lifecycle scripts for a normal npm installation.</p><p>With Nix on macOS or Linux, install the latest release from Pi&#39;s flake. Nix builds Pi from source:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github:earendil-works/pi/stable</span></span></code></pre></div><p>Older Nix versions use <code>nix profile install</code> instead. Update with <code>nix profile upgrade pi</code>; <code>pi update</code> cannot update a Nix installation. To pin a release, use a tag such as <code>github:earendil-works/pi/v1.0.0</code>.</p><p>Verify the installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="_2-start-pi" tabindex="-1">2. Start Pi <a class="header-anchor" href="#_2-start-pi" aria-label="Permalink to &quot;2. Start Pi&quot;">​</a></h2><p>Change to the folder you want Pi to work with, then start it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span></span></code></pre></div><p>The working folder helps Pi discover relevant files, instructions, and configuration. Pi also uses it to group saved sessions.</p><p align="center"><img src="`+e+'" alt="Pi running in a terminal with a conversation, input editor, and status footer" width="750"></p><p>The interface shows your conversation, an editor for prompts and commands, and a footer with the current folder, model, and session status. See <a href="./usage.html">Use Pi in the terminal</a> to learn how to add files, run commands, direct ongoing work, and manage results.</p><h2 id="_3-choose-a-model" tabindex="-1">3. Choose a model <a class="header-anchor" href="#_3-choose-a-model" aria-label="Permalink to &quot;3. Choose a model&quot;">​</a></h2><p>A <strong>model</strong> generates Pi&#39;s responses. A <strong>provider</strong> is the service or account Pi uses to access that model.</p><p>In Pi, run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login</span></span></code></pre></div><p>Choose a provider, then follow the prompts to use a subscription or store an API key. Run <code>/model</code> afterward if you want to select a different available model.</p><p>See <a href="./models.html">Choose a model and provider</a> for supported providers, environment-variable authentication, local models, and custom endpoints.</p><h2 id="_4-give-pi-a-task" tabindex="-1">4. Give Pi a task <a class="header-anchor" href="#_4-give-pi-a-task" aria-label="Permalink to &quot;4. Give Pi a task&quot;">​</a></h2><p>Pi shows each file read, search, command, and edit it performs. It does not ask before every tool call.</p><p>Enter a task that matches your work, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Summarize @meeting-notes.md and save the action items to action-items.md.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain how this repository is structured and how to run its checks.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compare @previous.csv with @current.csv and summarize the important changes.</span></span></code></pre></div><p>Type <code>@</code> in the editor to search for a file instead of entering its full path. When Pi finishes, review its response and any changed files. Use version control or backups for important work. For untrusted or unattended work, use a container or another sandbox. See <a href="./security.html">Security</a>.</p><h2 id="continue-later" tabindex="-1">Continue later <a class="header-anchor" href="#continue-later" aria-label="Permalink to &quot;Continue later&quot;">​</a></h2><p>Pi saves sessions automatically. Exit Pi, then resume the most recent session for the same working folder with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span></code></pre></div><p>Use <code>/resume</code> to choose another saved session. See <a href="./sessions.html">Continue or branch a session</a> for session naming, branching, compaction, export, and sharing.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./usage.html">Use Pi interactively</a> to learn input, commands, shortcuts, and queued messages.</li><li><a href="./configuration.html#context-files">Add instructions</a> that Pi should follow whenever it works in a folder.</li><li><a href="./models.html">Choose a model and provider</a>.</li></ul><h3 id="choose-how-to-customize-pi" tabindex="-1">Choose how to customize Pi <a class="header-anchor" href="#choose-how-to-customize-pi" aria-label="Permalink to &quot;Choose how to customize Pi&quot;">​</a></h3><p>Start with the least powerful mechanism that meets your need:</p><table tabindex="0"><thead><tr><th>Need</th><th>Start with</th></tr></thead><tbody><tr><td>Give Pi persistent instructions for a folder</td><td><a href="./configuration.html#context-files"><code>AGENTS.md</code></a></td></tr><tr><td>Reuse a prompt from the <code>/</code> menu</td><td><a href="./prompt-templates.html">Prompt template</a></td></tr><tr><td>Add task-specific instructions and supporting files</td><td><a href="./skills.html">Skill</a></td></tr><tr><td>Add executable tools, commands, or event handlers</td><td><a href="./extensions.html">Extension</a></td></tr><tr><td>Build a custom terminal component</td><td><a href="./tui.html">Terminal UI</a></td></tr><tr><td>Connect an unsupported model service</td><td><a href="./custom-provider.html">Custom provider</a></td></tr><tr><td>Install or distribute several resources</td><td><a href="./packages.html">Pi package</a></td></tr></tbody></table><h2 id="uninstall-pi" tabindex="-1">Uninstall Pi <a class="header-anchor" href="#uninstall-pi" aria-label="Permalink to &quot;Uninstall Pi&quot;">​</a></h2><p>If you installed Pi with npm, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @earendil-works/pi-coding-agent</span></span></code></pre></div><p>If you used the installer, run it again and choose <strong>Uninstall Pi</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pi.dev/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>If you installed Pi with Nix, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span></span></code></pre></div><p>None of these methods removes configuration, credentials, sessions, or installed Pi packages from <code>~/.pi/agent/</code>.</p>',50)])])}const m=a(o,[["render",l]]);export{g as __pageData,m as default};
